from lib import *
S = SS('w86')
steps = [
    step("对 example.com 的 HTTP/3 请求(aioquic):ALPN 协商出 h3。QUIC 连接建立(握手到可以发请求)逐次 194、167、325、169、171 ms,中位 171 ms——正好是一个往返(这条路径上的 RTT 约 160 ms);请求发出到首字节中位 163 ms(又一个往返);总计中位 348 ms,取回 577 字节的首页。对照 TCP + TLS 1.3 + HTTP/2:TCP 握手 160 ms + TLS 握手 164 ms + 请求到首字节 343 ms,总计 680 ms。HTTP/3 总共快了 332 ms,约 2 个 RTT。其中一个往返来自握手:QUIC 把传输握手和 TLS 握手合在一起,1 个 RTT 就能发请求,而 TCP + TLS 1.3 要 2 个(171 对 324 ms)。另一个往返来自我这次 HTTP/2 测量里“请求到首字节”用了 343 ms(约 2 个 RTT),比 HTTP/3 的 163 ms 多一个——原因我没有查明(可能与 HTTP/2 开头的 SETTINGS 交换有关,没有验证)。", t=tl(S(1)), mark=lidx(S(1), 'HTTP/3:ALPN h3'), done=lidx(S(1), 'HTTP/2:TCP 握手'), b=bars([['HTTP/3 握手', 171, '171 ms'], ['HTTP/2 TCP+TLS 握手', 324, '160 + 164 ms'], ['HTTP/3 总计', 348, '348 ms'], ['HTTP/2 总计', 680, '680 ms']], 680, mark=[0, 2], done=[1, 3]), kv=KV([['QUIC 握手', '约 1 个 RTT(171 ms)'], ['TCP + TLS 握手', '约 2 个 RTT(324 ms)'], ['整次取回首页', 'HTTP/3 348 ms,HTTP/2 680 ms']], ['QUIC 握手'])),
    step("QUIC 在线路上的样子(抓 en0,一次 HTTP/3 请求):整个请求 21 个 UDP 数据报,共 9418 字节;客户端→服务器 10 个 / 2984 字节,服务器→客户端 11 个 / 6434 字节。第一个数据报是客户端的 Initial,长包头,版本 0x00000001(QUIC v1),DCID 8 字节,长度正好 1200 字节——规范要求包含 Initial 的数据报至少 1200 字节,故意填充,防止 QUIC 服务器被拿来做反射放大。+156.2 ms 服务器回 Initial(1200 字节);+157.0 ms 客户端又发一个 1200 字节的 Initial(DCID 变成了服务器给的 20 字节);+158.6 ms 服务器连发 4 个 Handshake 包(3 × 1200 + 552 字节,证书和握手消息);客户端回 3 个 60 字节的 Handshake(确认),+164.9 ms 一个 213 字节的 Handshake(Finished),+165.2 ms 第一个短包头(1-RTT)包。握手之后的包都用短包头,只有一个标志位,比长包头紧凑。", t=tl(S(2)), mark=lidx(S(2), '+    0.0 ms', '+  156.2 ms', '+  165.2 ms'), done=lidx(S(2), '整个请求在线上', '客户端第一个数据报'), b=bars([['客户端→服务器', 2984, '2984 字节'], ['服务器→客户端', 6434, '6434 字节'], ['客户端 Initial', 1200, '1200 字节']], 6434, mark=[2], done=[0, 1]), kv=KV([['整个请求', '21 个数据报 / 9418 字节'], ['第一个数据报', '1200 字节 Initial(填充)'], ['握手完成', '约 165 ms,第一个 1-RTT 短包头包']], ['第一个数据报'])),
    step("会话恢复与 0-RTT,对 example.com(这一节我改正过:最初版本把 session ticket 的回调写进了 QuicConfiguration,aioquic 悄悄忽略,所以“收到 0 个 ticket”是我自己的错,不是服务器的;回调要传给 connect())。第一次完整握手收到 2 个 session ticket,但 ticket 里的 max_early_data_size 是空的——服务器不接受 early data。之后各 4 次:A 完整握手,响应头中位 524 ms;B 带 ticket 恢复会话、等握手完成,中位 518 ms,session_resumed = True;C 想用 0-RTT(握手没完成就发请求),中位 567 ms,session_resumed = True,但 early_data_accepted = False,请求并没有被当作 0-RTT 接受。三者没有可见的差别(个别一次 1352 ms 是网络抖动)。所以对 example.com,会话恢复能做到,0-RTT 做不到——和 w93 里 example.com 的 TLS 1.3 ticket 也是 Max Early Data 0 一致。", t=tl(S(3)), mark=lidx(S(3), '第一次(完整握手)'), done=lidx(S(3), 'A 完整握手', 'B 带 ticket', 'C 带 ticket'), kv=KV([['session ticket', '收到 2 个,max_early_data_size 为空'], ['会话恢复', 'session_resumed = True'], ['0-RTT', 'early_data_accepted = False,服务器不接受']], ['0-RTT'])),
    step("0-RTT 在本机测成了:我自己的 aioquic 服务端开了 session ticket 和 early data(ticket 里 max_early_data_size = 4294967295,第一次完整握手响应头 218 ms),netlab 每个方向加 50 ms(往返 100 ms)。从开始连接到收到响应头,各 6 次的中位数:A 完整握手 209 ms;B 带 ticket 恢复、等握手完成再发请求 209 ms(session_resumed = True,没有省往返);C 带 ticket 的 0-RTT,握手没完成就把请求发出去,105 ms,early_data_accepted = True,约少了一个往返(104 ms,往返是 100 ms)。A、B 约 2 个往返(1 个握手 + 1 个请求),C 约 1 个往返。注意 B 行的 early_data_accepted 也是 True:它只表示服务器接受了 ticket 里的 early data 提议,B 并没有发 early data。响应体收完的时间差别小得多(519 / 514 / 461 ms),因为纯 Python 的 aioquic 发 100 KB 本身就要约 300 ms,0-RTT 只省握手那一个往返。", t=tl(S(4)), mark=lidx(S(4), 'C 带 ticket,0-RTT'), done=lidx(S(4), '第一次(完整握手', 'A 完整握手', 'B 带 ticket'), b=bars([['A 完整握手', 209, '209 ms'], ['B 恢复,等握手', 209, '209 ms'], ['C 0-RTT', 105, '105 ms']], 209, mark=[2], done=[0, 1]), kv=KV([['完整握手 / 恢复', '约 2 个往返,209 / 209 ms'], ['0-RTT', '约 1 个往返,105 ms'], ['节省', '约 1 个 RTT(104 ms)']], ['0-RTT'])),
    step("丢包下 HTTP/3 与 HTTP/2 谁更好?本机服务器(自签名证书),同时取 10 个 100 KB 的资源,一条连接,各 4 次,netlab 每方向 50 ms。0% 丢包:HTTP/2(python h2 对 python h2)中位 612 ms;HTTP/3(aioquic 对 aioquic)840 ms。3% 丢包:HTTP/2 917 ms(其中一次 1498 ms),HTTP/3 14606 ms,最好的一次也要 10 秒以上——aioquic 在丢包下慢了十几倍。这个数字能不能算 HTTP/3 的缺点?两边的实现成熟度根本不可比(纯 Python 的 aioquic,客户端和服务端还在同一个进程里;HTTP/2 用的是操作系统的 TCP 栈)。我换成原生实现重测。", t=tl(S(5)), mark=lidx(S(5), '3%       HTTP/2', '3%       HTTP/3'), done=lidx(S(5), '0%       HTTP/2', '0%       HTTP/3'), b=bars([['0% HTTP/2', 612, '612 ms'], ['0% HTTP/3', 840, '840 ms'], ['3% HTTP/2', 917, '917 ms'], ['3% HTTP/3', 14606, '14606 ms']], 14606, mark=[3], done=[0, 1, 2]), kv=KV([['0% 丢包', 'H2 612 ms,H3 840 ms'], ['3% 丢包', 'H2 917 ms,H3 14606 ms'], ['下一步', '换成原生实现重测']], ['下一步'])),
    step("原生实现对照:客户端换成 curl 8.22(C 写的 ngtcp2 / nghttp3 / nghttp2),服务端换成 Caddy 2.11(Go 的 quic-go 与标准库 HTTP/2),和 aioquic、python h2 交叉成 2×2。3% 丢包、每方向 50 ms,同时取 10 个 100 KB,每格 4 次,中位数:HTTP/3——aioquic 客户端 → aioquic 服务端 13189 ms;aioquic 客户端 → Caddy 7140 ms;curl → aioquic 服务端 1941 ms;curl → Caddy 964 ms。HTTP/2——python h2 → python h2 714 ms;python h2 → Caddy 1167 ms;curl → python h2 731 ms;curl → Caddy 702 ms。0% 丢包时 curl → Caddy 的 HTTP/3 是 392 ms,HTTP/2 是 339 ms。所以:aioquic 的 13 秒主要是客户端实现(换成 curl 后降到 1.9 秒,再换服务端到 Caddy 降到 0.96 秒);换成成熟实现后 HTTP/3 在 3% 丢包下是 964 ms,仍比 HTTP/2 的 702 ms 慢约 37%,在这个测试(一条连接、10 × 100 KB、两个方向各随机丢 3%)里没有显示出 HTTP/3 在丢包下更好。这不是 HTTP/3 的一般结论:每格只有 4 次,场景很小,而且 netlab 的丢包是随机、均匀的。", t=tl(S(6)), mark=lidx(S(6), '3%     HTTP/3'), done=lidx(S(6), '0%     HTTP/3', '0%     HTTP/2', '3%     HTTP/2', '自检'), b=bars([['aioquic → aioquic', 13189, '13189 ms'], ['aioquic → Caddy', 7140, '7140 ms'], ['curl → aioquic', 1941, '1941 ms'], ['curl → Caddy', 964, '964 ms'], ['(对照)HTTP/2 curl → Caddy', 702, '702 ms']], 13189, mark=[3], done=[0, 1, 2, 4]), kv=KV([['原生 HTTP/3(curl → Caddy)', '3% 丢包 964 ms'], ['原生 HTTP/2(curl → Caddy)', '3% 丢包 702 ms'], ['aioquic → aioquic', '13189 ms,实现问题为主']], ['原生 HTTP/3(curl → Caddy)'])),
]
